with flagged as (select *, case when started_at - lag(started_at) over (partition by device order by started_at, id) > interval '60' day then 1 else 0 end as is_new_burst from sessions), sessions_sessions as (select *, sum(is_new_burst) over (partition by device order by started_at, id rows between unbounded preceding and current row) as burst_id from flagged) select s.id, s.customer_id, s.device, s.browser, s.started_at, s.is_new_burst, s.burst_id, case when device rlike '^(tablet|mobile)$' then 'OTHER_ZONE' when device rlike '^(desktop)$' then 'GROUP_A' else 'GROUP_B' end as device_zone, (select max(x.balance) from accounts x where x.customer_id = s.customer_id) as max_account_balance from sessions_sessions s order by id nulls last, device;
